import { CerebralComponent } from './CerebralComponent'
import { View } from 'cerebral'

// Connect decorator for binding cerebral state/sequences to component properties
export function connect(dependencies: Record<string, any> | null) {
  return function (target: any) {
    const targetNgOnInit = target.prototype.ngOnInit
    const targetNgOnDestroy = target.prototype.ngOnDestroy
    const targetNgAfterViewInit = target.prototype.ngAfterViewInit
    const targetNgOnChanges = target.prototype.ngOnChanges

    // Set up Cerebral connection in ngOnInit
    target.prototype.ngOnInit = function (
      this: CerebralComponent & Record<string, any>
    ) {
      if (targetNgOnInit) {
        targetNgOnInit.call(this)
      }

      if (this.view) return

      if (!this._app) {
        throw new Error(
          'Cannot connect to Cerebral controller. Make sure you have injected AppService.'
        )
      }

      this.onUpdate = (changes: any, force: boolean) => {
        if (this.view) {
          this.view.updateFromState(changes, this.props, force)
          this.view.render(
            this.props,
            (props: any) => {
              Object.assign(this, props)
            },
            false
          )
        }
        this._cdr.detectChanges()
      }

      this.view = new View({
        dependencies,
        props: this.props || {},
        controller: this._app,
        displayName: this.constructor.name,
        onUpdate: this.onUpdate,
      })

      this.view.mount()
      this.view.render(
        this.props || {},
        (props: any) => {
          Object.assign(this, props)
        },
        true
      )
    }

    // Clean up view in ngOnDestroy
    target.prototype.ngOnDestroy = function (
      this: CerebralComponent & Record<string, any>
    ) {
      if (targetNgOnDestroy) {
        targetNgOnDestroy.call(this)
      }

      if (this.view) {
        this.view.unMount()
        this.view = null
      }
    }

    // Pass through other lifecycle hooks
    target.prototype.ngAfterViewInit = function (
      this: CerebralComponent & Record<string, any>
    ) {
      if (targetNgAfterViewInit) {
        targetNgAfterViewInit.call(this)
      }
    }

    target.prototype.ngOnChanges = function (
      this: CerebralComponent & Record<string, any>
    ) {
      if (targetNgOnChanges) {
        targetNgOnChanges.call(this)
      }
    }

    return target
  }
}
